ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "ici_class", "primary_endpoint_is_multiple_or_composite", "ici_name", "primary_endpoint"
FROM public."clinical_trials"
WHERE "ici_class" = 'PD-L1, CTLA-4' AND "primary_endpoint_is_multiple_or_composite" = 'Multiple';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "class_of_ici", "priamry_multiple_composite_or_co_primary_endpoints", "name_of_ici", "primary_endpoint"
FROM public."clinical_trials"
WHERE "class_of_ici" = 'PD-L1, CTLA-4' AND "priamry_multiple_composite_or_co_primary_endpoints" = 'Multiple';
